  .text(project => project.name);

import { scaleLinear } from "d3";

const x = scaleLinear()
  .domain([0, 100])
  .range([0, 640])
  .clamp(true);

import * as d3 from "d3";

const width = 640;
const height = 320;
const svg = d3.select("#chart").attr("viewBox", [0, 0, width, height].join(" "));
const x = d3.scaleBand().domain(data.map(item => item.name)).range([0, width]).padding(0.1);
const y = d3.scaleLinear().domain([0, d3.max(data, item => item.value) ?? 0]).nice().range([height, 0]);

svg.selectAll("rect")
  .data(data)
  .join("rect")
  .attr("x", item => x(item.name) ?? 0)
  .attr("y", item => y(item.value))
  .attr("width", x.bandwidth())
  .attr("height", item => height - y(item.value));
